# Part 8 (2.7): personal accounts in a real browser — e-mail sign-up + verification, Google sign-in through a local fake
# OpenID Connect provider, linking, forgot password, profile, class join, isolation, session expiry, guest import,
# account deletion — plus the cursor parallax (desktop, touch, reduced motion, click-through, pausing) and accessibility.
# Needs the server started with MAIL_DEV_DIR=/tmp/nlmails and the fake Google on :4556 (see tests/e2e/run.sh).
# usage: python3 tests/e2e/part8.py <out-dir>
import asyncio, sys, json, os, glob, subprocess, re
from playwright.async_api import async_playwright
OUT=sys.argv[1]; BASE='http://127.0.0.1:3990'; FAKE='http://127.0.0.1:4556'
MAILS=os.environ.get('MAIL_DEV_DIR','/tmp/nlmails'); DB=os.environ.get('E2E_DATABASE_URL','postgres://postgres@127.0.0.1:5433/netlab_e2e')
ROOT=os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
AXE_PATH=os.path.join(ROOT,'node_modules','axe-core','axe.min.js')
issues=[]
def bad(m): issues.append(m); print('  ✗',m)
def ok(m): print('  ✓',m)
def check(c,m): ok(m) if c else bad(m)
def sql(q): return subprocess.check_output(['psql',DB,'-tAc',q]).decode().strip()
def mail_to(addr):
    ms=[json.load(open(f)) for f in sorted(glob.glob(MAILS+'/*.json'))]; ms=[m for m in ms if m['to']==addr]
    return ms[-1] if ms else None
def link(m,kind): x=re.search(r'#/'+kind+r'/([A-Za-z0-9_-]+)',m['text']); return x and x.group(1)
async def fake_next(ctx,**w): await ctx.request.post(FAKE+'/_next',data=json.dumps(w),headers={'Content-Type':'application/json'})
async def wait_auth_done(pg):
    await pg.wait_for_function("()=>!document.body.classList.contains('authmode') && !/auth-result/.test(location.hash)",timeout=10000); await pg.wait_for_timeout(500)
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch()
        print('== e-mail sign-up on a phone, verification link, guest work imported')
        A=await b.new_context(viewport={'width':390,'height':844},has_touch=True,is_mobile=True); pg=await A.new_page(); E=[]; pg.on('pageerror',lambda e:E.append(str(e)))
        await pg.goto(BASE+'/#/'); await pg.wait_for_selector('.hero')
        await pg.evaluate("localStorage.setItem('netlab-v2',JSON.stringify({name:'',done:{},hints:{},timers:{},att:{},explain:{},flags:{},given:{},wrong:{},lessons:{w1:{visited:['s1','s2'],checks:[]}}}))")
        await pg.goto(BASE+'/#/register'); await pg.wait_for_selector('.authcard form')
        ov=await pg.evaluate('document.documentElement.scrollWidth-innerWidth'); check(ov<=0,'register page has no horizontal scroll at 390px')
        check(await pg.locator('.gbtn').count()==1 and 'ดำเนินการต่อด้วย Google' in await pg.inner_text('.gbtn'),'"ดำเนินการต่อด้วย Google" button is shown')
        f=pg.locator('.authcard form input')
        await f.nth(0).fill('สมชาย ใจดี'); await f.nth(1).fill('somchai.p8@example.com'); await f.nth(2).fill('Netlab2026'); await f.nth(3).fill('Netlab2026')
        await pg.locator('.authcard button[type=submit]').tap(); await pg.wait_for_timeout(300)
        check('ยอมรับเงื่อนไข' in await pg.inner_text('.authmsg'),'cannot sign up without accepting terms (Thai message)')
        await pg.locator('#acc').check(); await pg.locator('.authcard button[type=submit]').tap(); await pg.wait_for_selector('text=ตรวจสอบอีเมลของคุณ')
        check(True,'after sign-up the page asks to check e-mail'); await pg.screenshot(path=f'{OUT}/p8_checkmail_390.png')
        await pg.goto(BASE+'/#/login'); await pg.wait_for_selector('.authcard form'); await pg.fill('.authcard form input >> nth=0','somchai.p8@example.com'); await pg.fill('.authcard form input >> nth=1','Netlab2026')
        await pg.locator('.authcard button[type=submit]').tap(); await pg.wait_for_selector('button:has-text("ส่งลิงก์ยืนยันอีกครั้ง")')
        check('ยังไม่ได้ยืนยันอีเมล' in await pg.inner_text('.authmsg'),'login before verifying explains why and offers to resend the link')
        m=mail_to('somchai.p8@example.com'); check(m and 'ยืนยันอีเมล' in m['subject'] and m['html'].count('href')>=1,'verification e-mail was sent (Thai subject, button link)')
        await pg.goto(BASE+'/#/verify/'+link(m,'verify')); await pg.locator('button:has-text("ยืนยันอีเมล")').tap()
        await pg.wait_for_selector('.modal-back:has-text("ผูกความคืบหน้าเข้าบัญชี")',timeout=10000)
        check(True,'after verifying, the student is signed in and offered to import guest work (asks first)')
        await pg.locator('.modal-back button:has-text("ผูกเข้าบัญชีนี้")').tap(); await pg.wait_for_selector('.modal-back .msg.ok'); await pg.locator('.modal-back button:has-text("เสร็จสิ้น")').tap()
        aid=sql("SELECT id FROM users WHERE email='somchai.p8@example.com'")
        check(sql(f"SELECT count(*) FROM lesson_progress WHERE user_id={aid}")!='0','guest reading progress now belongs to the account')
        await pg.goto(BASE+'/#/profile'); await pg.wait_for_selector('.profgrid')
        await pg.fill('.profgrid form input >> nth=0','สมชาย P8'); await pg.locator('.avopt').nth(3).tap(); await pg.locator('.profgrid form button[type=submit]').first.tap(); await pg.wait_for_timeout(800)
        check(sql(f"SELECT display_name||'|'||avatar FROM users WHERE id={aid}")=='สมชาย P8|c3','profile edits are saved on the server')
        cls=sql("SELECT code FROM classes LIMIT 1")
        await pg.fill('input[placeholder="เช่น K7Q2MP"]',cls.lower()); await pg.locator('button:has-text("เข้าร่วมห้องเรียน")').tap(); await pg.wait_for_selector('text=อยู่ในห้อง')
        check(sql(f"SELECT class_id IS NOT NULL FROM users WHERE id={aid}")=='t','student joins the teacher\'s class later with the class code')
        await pg.screenshot(path=f'{OUT}/p8_profile_390.png',full_page=True)
        check(not E,'no JS errors '+'; '.join(E[:2]))

        print('== scores follow the account to another device; another student sees nothing')
        r=await pg.request.post(BASE+'/api/lessons/w2/quiz',data={'kind':'pre','answers':json.loads(subprocess.check_output(['node','-e',"const L=require('./content/lessons/w2.js');console.log(JSON.stringify(L.quiz.map(q=>q.type==='choice'?q.correct:q.type==='multi'?q.correct:q.type==='tf'?q.answer:q.answers[0])))"],cwd=ROOT))},headers={'X-NetLab':'1'})
        D2=await b.new_context(viewport={'width':1366,'height':860}); p2=await D2.new_page()
        await p2.goto(BASE+'/#/login'); await p2.wait_for_selector('.authcard form'); await p2.fill('.authcard form input >> nth=0','somchai.p8@example.com'); await p2.fill('.authcard form input >> nth=1','Netlab2026'); await p2.click('.authcard button[type=submit]')
        await wait_auth_done(p2); await p2.goto(BASE+'/#/results'); await p2.wait_for_timeout(1200)
        me=await (await D2.request.get(BASE+'/api/me')).json(); check(me['lessons'].get('w2',{}).get('pre',{}).get('score')==10,'the same pre-test score appears on a second device')
        S2=await b.new_context(); await S2.request.post(BASE+'/api/auth/login',data={'username':'s2','password':'Stud1234'},headers={'X-NetLab':'1'})
        me2=await (await S2.request.get(BASE+'/api/me')).json(); check('w2' not in me2['lessons'] or 'pre' not in me2['lessons']['w2'],'another student does not see those scores')

        print('== Google sign-in through the provider (fake OIDC), linking, refusal to merge by e-mail')
        G=await b.new_context(viewport={'width':1366,'height':860}); pg=await G.new_page(); E=[]; pg.on('pageerror',lambda e:E.append(str(e)))
        await fake_next(G,sub='2200000000000000000001',email='google.p8@gmail.com',name='กูเกิ้ล พีแปด')
        await pg.goto(BASE+'/#/login'); await pg.wait_for_selector('.gbtn'); await pg.click('.gbtn'); await wait_auth_done(pg)
        check(pg.url.endswith('#/profile') and await pg.locator('.profhead').count()==1,'first Google sign-in creates the account and opens the profile to complete')
        gid=sql("SELECT user_id FROM auth_identities WHERE subject='2200000000000000000001'")
        await pg.evaluate("logout()"); await pg.wait_for_timeout(500)
        await pg.goto(BASE+'/#/login'); await pg.wait_for_selector('.gbtn'); await pg.click('.gbtn'); await wait_auth_done(pg)
        me=await (await G.request.get(BASE+'/api/me')).json(); check(str(me['user']['id'])==gid and sql("SELECT count(*) FROM users WHERE email='google.p8@gmail.com'")=='1','signing in with Google again opens the same account (no duplicate)')
        await fake_next(G,sub='2200000000000000000002',email='somchai.p8@example.com',name='x')
        X=await b.new_context(); xp=await X.new_page(); await xp.goto(BASE+'/#/login'); await xp.wait_for_selector('.gbtn'); await xp.click('.gbtn'); await xp.wait_for_selector('.authdone h1')
        check('มีบัญชี NetLab อยู่แล้ว' in await xp.inner_text('.authdone'),'Google account with an existing NetLab e-mail is not merged; the page explains how to link safely')
        await xp.screenshot(path=f'{OUT}/p8_google_taken.png')
        pa=await D2.new_page(); await fake_next(D2,sub='2200000000000000000002',email='somchai.p8@example.com',name='สมชาย')
        await pa.goto(BASE+'/#/profile'); await pa.wait_for_selector('.profgrid'); await pa.click('a.gbtn:has-text("เชื่อมบัญชี Google")'); await wait_auth_done(pa)
        check('เชื่อมแล้ว' in await pa.inner_text('.methods'),'student A links Google from the profile (signed in = owner proven)')
        await xp.goto(BASE+'/#/login'); await xp.wait_for_selector('.gbtn'); await xp.click('.gbtn'); await wait_auth_done(xp)
        me=await (await X.request.get(BASE+'/api/me')).json(); check(str(me['user']['id'])==aid,'now that Google account opens student A')
        check(not E,'no JS errors '+'; '.join(E[:2]))

        print('== forgot password by e-mail, session expiry, account deletion')
        F=await b.new_context(viewport={'width':1366,'height':860}); fp=await F.new_page()
        await fp.goto(BASE+'/#/login'); await fp.wait_for_selector('.authcard'); await fp.click('text=ลืมรหัสผ่าน?'); await fp.wait_for_selector('text=ส่งคำขอ')
        await fp.fill('.authcard form input >> nth=0','somchai.p8@example.com'); await fp.click('.authcard button[type=submit]'); await fp.wait_for_selector('.msg.ok')
        m=mail_to('somchai.p8@example.com'); check(m and 'รหัสผ่าน' in m['subject'],'reset e-mail sent')
        await fp.goto(BASE+'/#/reset/'+link(m,'reset')); await fp.wait_for_selector('.authcard form')
        await fp.fill('.authcard form input >> nth=0','Fresh2026pw'); await fp.fill('.authcard form input >> nth=1','Fresh2026pw'); await fp.click('.authcard button[type=submit]'); await wait_auth_done(fp)
        me=await (await D2.request.get(BASE+'/api/me')).json(); check(me['user'] is None,'resetting the password signed out the other device')
        sql(f"UPDATE sessions SET expires_at=now()-interval '1 minute' WHERE user_id={aid}")
        await fp.reload(); await fp.wait_for_timeout(1200); me=await (await F.request.get(BASE+'/api/me')).json(); check(me['user'] is None,'an expired session is treated as signed out')
        await fp.goto(BASE+'/#/login'); await fp.wait_for_selector('.authcard form'); await fp.fill('.authcard form input >> nth=0','somchai.p8@example.com'); await fp.fill('.authcard form input >> nth=1','Fresh2026pw'); await fp.click('.authcard button[type=submit]'); await wait_auth_done(fp)
        await fp.goto(BASE+'/#/profile'); await fp.wait_for_selector('details.danger'); await fp.click('details.danger summary')
        await fp.fill('details.danger input >> nth=0','ลบบัญชี'); await fp.fill('details.danger input >> nth=1','Fresh2026pw'); await fp.click('details.danger button[type=submit]'); await fp.wait_for_timeout(1200)
        check(sql(f"SELECT count(*) FROM users WHERE id={aid}")=='0' and sql(f"SELECT count(*) FROM quiz_attempts WHERE user_id={aid}")=='0','deleting the account removes the profile and every score')

        print('== cursor parallax')
        P=await b.new_context(viewport={'width':1366,'height':860}); pp=await P.new_page(); E=[]; pp.on('pageerror',lambda e:E.append(str(e)))
        await pp.goto(BASE+'/#/login'); await pp.wait_for_selector('.authwrap .px')
        check(await pp.locator('.authwrap .px > .px-l').count()==5,'login page has 5 parallax layers')
        await pp.mouse.move(683,430); await pp.wait_for_timeout(700)
        st0=await pp.evaluate("[...document.querySelectorAll('.px-l')].map(l=>l.style.transform)")
        await pp.mouse.move(1350,20,steps=8); await pp.wait_for_timeout(900)
        st1=await pp.evaluate("[...document.querySelectorAll('.px-l')].map(l=>{const m=l.style.transform.match(/translate3d\\(([-\\d.]+)px, ([-\\d.]+)px/);return m?[+m[1],+m[2]]:[0,0]})")
        mags=[abs(x)+abs(y) for x,y in st1]
        check(st1[0][0]>0 and st1[3][0]>st1[1][0]>st1[0][0] and st1[4][0]<0,f'layers move by depth: back slow, front faster, light against the cursor ({[round(x[0],1) for x in st1]})')
        check(max(abs(x) for x,_ in st1)<=12.5 and max(abs(y) for _,y in st1)<=12.5,'movement stays subtle (at most about 12 px)')
        check(await pp.evaluate("document.querySelector('.authcard').style.transform===''"),'the login form itself never moves')
        hit=await pp.evaluate("(()=>{const i=document.querySelector('.authcard input');const r=i.getBoundingClientRect();return document.elementFromPoint(r.x+r.width/2,r.y+r.height/2)===i})()")
        check(hit,'the background never blocks clicks or typing')
        await pp.mouse.move(1350,20,steps=4); await pp.wait_for_timeout(300); await pp.evaluate("document.dispatchEvent(new PointerEvent('pointerout',{relatedTarget:null}))"); await pp.wait_for_timeout(2200)
        st=await pp.evaluate("NLParallax.states()[0]"); check(abs(st['cx'])<0.1 and abs(st['cy'])<0.1 and st['tx']==0 and st['ty']==0,'when the cursor leaves the window the layers ease back to the centre')
        await pp.goto(BASE+'/#/lesson/w1/content'); await pp.wait_for_selector('.lsec'); check(await pp.locator('.px').count()==0,'lesson pages have no moving background')
        await pp.goto(BASE+'/#/sim/subnet'); await pp.wait_for_timeout(800); check(await pp.locator('.px').count()==0,'simulator pages have no moving background')
        await pp.goto(BASE+'/#/'); await pp.wait_for_selector('.hero .px'); check(True,'dashboard hero has the parallax background')
        r1=await pp.evaluate("NLParallax.states()[0].running")
        await pp.evaluate('window.scrollTo(0,2500)'); await pp.wait_for_timeout(700)
        r2=await pp.evaluate("NLParallax.states()[0].running")
        await pp.evaluate('window.scrollTo(0,0)'); await pp.wait_for_timeout(500)
        r3=await pp.evaluate("NLParallax.states()[0].running")
        check(r1 and not r2 and r3,f'animation pauses while the hero is off screen and resumes when back ({r1},{r2},{r3})')
        cnt=await pp.evaluate("NLParallax.count()"); check(cnt==1,'only one parallax instance alive after navigating (old ones destroyed)')
        check(not E,'no JS errors '+'; '.join(E[:2]))
        R=await b.new_context(viewport={'width':1366,'height':860},reduced_motion='reduce'); rp=await R.new_page()
        await rp.goto(BASE+'/#/login'); await rp.wait_for_selector('.px'); await rp.mouse.move(1300,50,steps=5); await rp.wait_for_timeout(600)
        t=await rp.evaluate("[...document.querySelectorAll('.px-l')].map(l=>l.style.transform)")
        check(await rp.locator('.px.px-still').count()==1 and all(re.match(r'translate3d\((-?0(\.0+)?)px, (-?0(\.0+)?)px',x) for x in t) and await rp.locator('.px-packet').count()==0,'reduced motion: background is completely still')
        T=await b.new_context(viewport={'width':390,'height':844},has_touch=True,is_mobile=True); tp=await T.new_page()
        await tp.goto(BASE+'/#/login'); await tp.wait_for_selector('.px'); await tp.touchscreen.tap(380,20); await tp.wait_for_timeout(500)
        t=await tp.evaluate("[...document.querySelectorAll('.px-l')].map(l=>l.style.transform)")
        check(all(re.match(r'translate3d\((-?0(\.0+)?)px, (-?0(\.0+)?)px',x) for x in t) and await tp.locator('.px-packet').count()<=3,'touch screens: no cursor tracking, only a few slow packets')
        ov=await tp.evaluate('document.documentElement.scrollWidth-innerWidth'); check(ov<=0,'no horizontal scroll at 390px')
        await tp.screenshot(path=f'{OUT}/p8_login_390.png',full_page=True)

        print('== accessibility of the account pages (axe WCAG 2.1 AA), light + dark')
        if os.path.exists(AXE_PATH):
            AXE=open(AXE_PATH).read(); viol=[]
            for theme in ['light','dark']:
                c=await b.new_context(viewport={'width':1366,'height':900},color_scheme=theme); cp=await c.new_page()
                await c.request.post(BASE+'/api/auth/login',data={'username':'s1','password':'Stud1234'},headers={'X-NetLab':'1'})
                for rt in ['#/profile','#/privacy','#/terms']:
                    await cp.goto(BASE+'/'+rt); await cp.wait_for_timeout(1200); await cp.add_script_tag(content=AXE)
                    v=await cp.evaluate("async()=>{const r=await axe.run(document,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21a','wcag21aa']}});return r.violations.map(v=>v.id+':'+v.nodes.length+' '+v.nodes.slice(0,2).map(n=>n.target.join(' ')).join(' | '))}")
                    if v: viol.append(f'{theme} {rt} {v}')
                c2=await b.new_context(viewport={'width':1366,'height':900},color_scheme=theme); cp=await c2.new_page()
                for rt in ['#/login','#/register','#/forgot']:
                    await cp.goto(BASE+'/'+rt); await cp.wait_for_timeout(1200); await cp.add_script_tag(content=AXE)
                    v=await cp.evaluate("async()=>{const r=await axe.run(document,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21a','wcag21aa']}});return r.violations.map(v=>v.id+':'+v.nodes.length+' '+v.nodes.slice(0,2).map(n=>n.target.join(' ')).join(' | '))}")
                    if v: viol.append(f'{theme} {rt} {v}')
            check(not viol,'axe: no violations on login, register, forgot, profile, terms, privacy '+' ;; '.join(viol[:4]))
        await b.close()
    print('\nISSUES',len(issues)); [print(' -',i) for i in issues]
    sys.exit(1 if issues else 0)
asyncio.run(main())
